//! Exact, reversible adapters for the two frozen benchmark source layouts.
use crate::Result;

pub fn read(path: impl AsRef<std::path::Path>) -> Result<String> {
    let path = path.as_ref();
    let text =
        std::fs::read_to_string(path).map_err(|error| format!("{}: {error}", path.display()))?;
    // Preserve pathlib.read_text's universal-newline behavior. Frozen source
    // anchors and generated bytes must also work with CRLF/CR checkouts.
    Ok(crate::artifact::snapshot::universal_newlines(text))
}

pub fn block<'a>(text: &'a str, declaration: &str) -> Result<&'a str> {
    let start = text
        .find(declaration)
        .ok_or_else(|| format!("missing source declaration: {declaration}"))?;
    let end = text[start..]
        .find("\n}")
        .ok_or("missing source closing boundary")?
        + start
        + 2;
    Ok(&text[start..end])
}

pub fn replace_once(text: &str, before: &str, after: &str, error: &str) -> Result<String> {
    if text.matches(before).count() != 1 {
        return Err(error.to_owned().into());
    }
    Ok(text.replacen(before, after, 1))
}

pub struct Edits<'a> {
    original: &'a str,
    changed: String,
    edits: Vec<(String, String, usize)>,
}
impl<'a> Edits<'a> {
    pub fn new(original: &'a str) -> Self {
        Self {
            original,
            changed: original.to_owned(),
            edits: Vec::new(),
        }
    }
    pub fn replace(&mut self, before: &str, after: &str, count: usize) -> Result<()> {
        if self.changed.matches(before).count() != count {
            return Err(format!("diagnostic source boundary changed: {before}").into());
        }
        self.changed = self.changed.replace(before, after);
        self.edits.push((before.into(), after.into(), count));
        Ok(())
    }
    pub fn before(&mut self, marker: &str, observation: &str) -> Result<()> {
        self.replace(marker, &(observation.to_owned() + marker), 1)
    }
    pub fn after(&mut self, marker: &str, observation: &str) -> Result<()> {
        self.replace(marker, &(marker.to_owned() + observation), 1)
    }
    pub fn finish(self) -> Result<String> {
        let mut restored = self.changed.clone();
        for (before, after, count) in self.edits.iter().rev() {
            if restored.matches(after.as_str()).count() != *count {
                return Err("non-reversible source observation".into());
            }
            restored = restored.replace(after, before);
        }
        if restored != self.original {
            return Err("diagnostic changed an original statement".into());
        }
        Ok(self.changed)
    }
}

pub fn method(
    text: &str,
    declaration: &str,
    transform: impl FnOnce(&str, &mut Edits<'_>) -> Result<()>,
) -> Result<String> {
    if text.matches(declaration).count() != 1 {
        return Err(format!("stream source declaration changed: {declaration}").into());
    }
    let start = text.find(declaration).ok_or("missing method")?;
    let end = start
        + text[start..]
            .find("\n    }")
            .ok_or("missing method boundary")?
        + 6;
    let original = &text[start..end];
    let mut edits = Edits::new(original);
    transform(original, &mut edits)?;
    Ok(format!(
        "{}{}{}",
        &text[..start],
        edits.finish()?,
        &text[end..]
    ))
}

pub fn top(
    text: &str,
    declaration: &str,
    transform: impl FnOnce(&mut Edits<'_>) -> Result<()>,
) -> Result<String> {
    let original = block(text, declaration)?;
    let mut edits = Edits::new(original);
    transform(&mut edits)?;
    Ok(text.replacen(original, &edits.finish()?, 1))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn changed_missing_or_ambiguous_boundaries_never_produce_partial_edits() {
        let text = "    pub fn example() {\n        original();\n    }\n";
        let patched = method(text, "    pub fn example(", |_, edit| {
            edit.replace("original();", "probe(); original();", 1)
        })
        .unwrap();
        assert!(patched.contains("probe(); original();"));
        assert!(
            method(
                &text.replace("original();", "original(); original();"),
                "    pub fn example(",
                |_, edit| edit.replace("original();", "probe(); original();", 1)
            )
            .is_err()
        );
        assert!(method(&text.repeat(2), "    pub fn example(", |_, _| Ok(())).is_err());
        assert!(replace_once("x x", "x", "y", "ambiguous").is_err());
    }
}
